// The result keys silent-flag-guard.test.js treats as a warning or a verdict:
// a boolean so named is something the page must say when it flips.
export const FLAG = /(cannot|can_not|exceed|fail|over_|_over|unsafe|short|insufficient|violat|lifted|too_|not_ok|warn|undersiz|overload|_ok$|^ok_|passes|^pass$|adequate|meets|complies|governs|required$|needs_|needed$|unstable|slides|tips|overturn|collapse|buckl|yield)/i;
